#include <iostream>
#include <cmath>

int main() {
    int n;
    std::cin >> n;

    int a = 1;
    int b = n;

    // Start from the square root and go downwards to find the largest divisor <= sqrt(n)
    for (int i = static_cast<int>(std::sqrt(n)); i >= 1; --i) {
        if (n % i == 0) {
            a = i;
            b = n / i;
            break;
        }
    }

    std::cout << a << " " << b << std::endl;

    return 0;
}

