int main() {
    int n;
    std::cin >> n;

    int a = 1, b = n;
    int min_diff = n - 1;

    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            int j = n / i;
            if (j - i < min_diff) {
                min_diff = j - i;
                a = i;
                b = j;
            }
        }
    }

    std::cout << a << " " << b << std::endl;

    return 0;
}
